<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/session.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../index.php');
function feedback_count($conn,$sql){$r=pg_query($conn,$sql);return $r?(int)pg_fetch_result($r,0,0):0;}$campaigns=feedback_count($conn,'SELECT COUNT(*) FROM feedback_campaigns');$active=feedback_count($conn,"SELECT COUNT(*) FROM feedback_campaigns WHERE status='active'");$participants=feedback_count($conn,'SELECT COUNT(*) FROM feedback_participants');$responses=feedback_count($conn,'SELECT COUNT(*) FROM feedback_submissions');$rate=$participants?round($responses/$participants*100,1):0;
$recent=pg_query($conn,"SELECT c.*,COUNT(DISTINCT p.id) participants,COUNT(DISTINCT s.id) responses FROM feedback_campaigns c LEFT JOIN feedback_participants p ON p.campaign_id=c.id LEFT JOIN feedback_submissions s ON s.campaign_id=c.id GROUP BY c.id ORDER BY c.created_at DESC LIMIT 8");$activity=pg_query($conn,"SELECT s.reference_code,s.submitted_at,c.title FROM feedback_submissions s JOIN feedback_campaigns c ON c.id=s.campaign_id ORDER BY s.submitted_at DESC LIMIT 8");admin_page_start('Overview','dashboard');?>
<div class="hero"><div><h2>Your feedback pulse</h2><p>See participation, response activity, and campaign health at a glance.</p></div><a class="btn" href="campaigns/index.php?action=new"><i class="fa-solid fa-plus"></i> New campaign</a></div><div class="grid stats"><div class="stat"><i class="fa-solid fa-bullhorn"></i><strong><?=$campaigns?></strong><span>Total campaigns</span></div><div class="stat"><i class="fa-solid fa-signal"></i><strong><?=$active?></strong><span>Active now</span></div><div class="stat"><i class="fa-solid fa-message"></i><strong><?=$responses?></strong><span>Responses received</span></div><div class="stat"><i class="fa-solid fa-percent"></i><strong><?=$rate?>%</strong><span>Overall response rate</span></div></div>
<div class="grid two-col"><div class="card"><h3>Recent campaigns</h3><div class="table-wrap"><table><thead><tr><th>Campaign</th><th>Status</th><th>Progress</th></tr></thead><tbody><?php if($recent):while($c=pg_fetch_assoc($recent)):$pct=(int)$c['participants']?round((int)$c['responses']/(int)$c['participants']*100):0;?><tr><td><a href="responses/index.php?campaign_id=<?=(int)$c['id']?>" style="font-weight:800;text-decoration:none"><?=h($c['title'])?></a><div class="help"><?=(int)$c['responses']?> of <?=(int)$c['participants']?> invited</div></td><td><span class="badge <?=h($c['status'])?>"><?=h(ucfirst($c['status']))?></span></td><td><div class="progress"><span style="width:<?=$pct?>%"></span></div><small><?=$pct?>%</small></td></tr><?php endwhile;endif;if(!$recent||pg_num_rows($recent)===0):?><tr><td colspan="3" class="empty">Create your first feedback campaign.</td></tr><?php endif;?></tbody></table></div></div><div class="card"><h3>Latest responses</h3><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Campaign</th><th>Received</th></tr></thead><tbody><?php if($activity):while($a=pg_fetch_assoc($activity)):?><tr><td><span class="badge"><?=h($a['reference_code'])?></span></td><td><?=h($a['title'])?></td><td><?=h(timeAgo($a['submitted_at']))?></td></tr><?php endwhile;endif;if(!$activity||pg_num_rows($activity)===0):?><tr><td colspan="3" class="empty">No responses yet.</td></tr><?php endif;?></tbody></table></div></div></div><?php admin_page_end();?>
